'use client';

import React from 'react';
import { motion } from 'framer-motion';

interface GameBlogPlaceholderProps {
    onBack: () => void;
    initialBounds?: { x: number, y: number, w: number, h: number } | null;
}

const GameBlogPlaceholder: React.FC<GameBlogPlaceholderProps> = ({ onBack, initialBounds }) => {
    const isInitialParamsValid = initialBounds && initialBounds.x !== undefined;

    return (
        <motion.div
            initial={isInitialParamsValid && initialBounds ? {
                opacity: 0,
                left: initialBounds.x,
                top: initialBounds.y,
                width: initialBounds.w,
                height: initialBounds.h,
                scale: 0.1,
                borderRadius: 20
            } : { opacity: 0, scale: 0.98, left: 0, top: 0, width: '100%', height: '100%' }}
            animate={{
                opacity: 1,
                left: 0,
                top: 0,
                width: '100%',
                height: '100%',
                scale: 1,
                borderRadius: 0,
                transition: { duration: 0.5, ease: [0.19, 1, 0.22, 1] }
            }}
            exit={isInitialParamsValid && initialBounds ? {
                opacity: 0,
                left: initialBounds.x,
                top: initialBounds.y,
                width: initialBounds.w,
                height: initialBounds.h,
                scale: 0.1,
                borderRadius: 20,
                transition: { duration: 0.4, ease: "easeInOut" }
            } : { opacity: 0, scale: 0.98 }}
            className="fixed z-[200] flex items-center justify-center p-0 pointer-events-auto bg-black/95 backdrop-blur-sm overflow-hidden origin-top-left"
            onClick={(e) => e.stopPropagation()}
        >
            <div className="w-full max-w-lg border-2 border-purple-500/50 bg-black relative shadow-[0_0_30px_rgba(168,85,247,0.15)] flex flex-col p-12 text-center overflow-hidden">

                <div className="mb-6 relative z-10">
                    <div className="w-16 h-16 bg-purple-500/20 text-purple-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-purple-500/50 animate-pulse">
                        <span className="font-mono text-2xl font-bold">!</span>
                    </div>
                    <h2 className="text-2xl font-bold text-purple-500 font-mono tracking-widest mb-2">ACCESS_DENIED</h2>
                    <p className="text-purple-300/70 font-mono text-sm">
                        Node "BLOG_ARCHIVE" is currently under construction.
                    </p>
                </div>

                <div className="relative z-10">
                    <div className="bg-purple-900/10 border border-purple-500/30 p-4 mb-8">
                        <p className="text-xs font-mono text-purple-400">ESTIMATED COMPLETION: Q1 2026</p>
                    </div>

                    <button
                        onClick={onBack}
                        className="bg-purple-600 hover:bg-purple-500 text-black font-bold py-3 px-8 uppercase tracking-widest text-sm transition-colors border border-purple-400"
                    >
                        [RETURN]
                    </button>
                </div>

                {/* Scanlines */}
                <div className="absolute inset-0 pointer-events-none opacity-10 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%]" />
            </div>
        </motion.div>
    );
};

export default GameBlogPlaceholder;

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface GameIdentityCoreProps {
    onBack: () => void;
    initialBounds?: { x: number, y: number, w: number, h: number } | null;
}

type Tab = 'profile' | 'stats' | 'history';

const GameIdentityCore: React.FC<GameIdentityCoreProps> = ({ onBack, initialBounds }) => {
    const [activeTab, setActiveTab] = useState<Tab>('profile');

    const isInitialParamsValid = initialBounds && initialBounds.x !== undefined;

    return (
        <motion.div
            initial={isInitialParamsValid && initialBounds ? {
                opacity: 0,
                left: initialBounds.x,
                top: initialBounds.y,
                width: initialBounds.w,
                height: initialBounds.h,
                scale: 0.1,
                borderRadius: 20
            } : { opacity: 0, scale: 0.98, left: 0, top: 0, width: '100%', height: '100%' }}
            animate={{
                opacity: 1,
                left: 0,
                top: 0,
                width: '100%',
                height: '100%',
                scale: 1,
                borderRadius: 0,
                transition: { duration: 0.5, ease: [0.19, 1, 0.22, 1] }
            }}
            exit={isInitialParamsValid && initialBounds ? {
                opacity: 0,
                left: initialBounds.x,
                top: initialBounds.y,
                width: initialBounds.w,
                height: initialBounds.h,
                scale: 0.1,
                borderRadius: 20,
                transition: { duration: 0.4, ease: "easeInOut" }
            } : { opacity: 0, scale: 0.98 }}
            className="fixed z-[200] flex items-center justify-center p-0 pointer-events-auto bg-black/95 backdrop-blur-sm overflow-hidden origin-top-left"
            onClick={(e) => e.stopPropagation()}
        >
            <div className="w-full max-w-4xl bg-black border-2 border-amber-500/50 relative shadow-[0_0_30px_rgba(245,158,11,0.15)] flex flex-col h-[600px] overflow-hidden">

                {/* Navigation Tabs */}
                <div className="flex border-b border-amber-500/30">
                    {['profile', 'stats', 'history'].map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab as Tab)}
                            className={`flex-1 py-4 font-mono text-sm uppercase tracking-widest transition-colors border-r border-amber-500/30 last:border-r-0 hover:bg-amber-500/10 ${activeTab === tab ? 'bg-amber-500 text-black font-bold' : 'text-amber-500'
                                }`}
                        >
                            [{tab.toUpperCase()}]
                        </button>
                    ))}
                    <button
                        onClick={onBack}
                        className="px-6 py-4 font-mono text-sm text-amber-500 hover:bg-red-900/20 hover:text-red-500 transition-colors border-l border-amber-500/30"
                    >
                        [X]
                    </button>
                </div>

                {/* Content Area */}
                <div className="flex-1 p-8 md:p-12 font-mono text-amber-500 overflow-y-auto relative">
                    <AnimatePresence mode="wait">
                        {activeTab === 'profile' && (
                            <motion.div
                                key="profile"
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="grid grid-cols-1 md:grid-cols-3 gap-8 h-full"
                            >
                                <div className="md:col-span-1 border border-amber-500/30 p-2 bg-black">
                                    <video
                                        src="/IMG_3961.mov"
                                        className="w-full h-full object-cover grayscale opacity-80"
                                        autoPlay
                                        loop
                                        muted
                                        playsInline
                                    />
                                </div>
                                <div className="md:col-span-2 space-y-6">
                                    <h2 className="text-3xl font-bold border-b border-amber-500/30 pb-2">PROFILE: PAMIMO AKINJIDE</h2>
                                    <div className="grid grid-cols-2 gap-4 text-sm">
                                        <div className="opacity-70">CLASS:</div><div>BUILDER</div>
                                        <div className="opacity-70">BASE:</div><div>TORONTO, CA</div>
                                        <div className="opacity-70">STATUS:</div><div>ONLINE</div>
                                    </div>
                                    <div className="bg-amber-500/10 p-4 border border-amber-500/30 mt-4">
                                        <p className="leading-relaxed text-sm opacity-90">
                                            "Mission: Bridging the gap between technical rigor and human-centric strategy. Operating with high agency in complex systems."
                                        </p>
                                    </div>
                                </div>
                            </motion.div>
                        )}

                        {activeTab === 'stats' && (
                            <motion.div
                                key="stats"
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="space-y-8"
                            >
                                <h2 className="text-2xl font-bold mb-6">&gt; ATTRIBUTE_MATRIX</h2>

                                <div className="space-y-4">
                                    {[
                                        { label: 'PRODUCT_SENSE', val: 95 },
                                        { label: 'STRATEGIC_ALIGNMENT', val: 90 },
                                        { label: 'TECHNICAL_FLUENCY', val: 85 },
                                        { label: 'STAKEHOLDER_MGMT', val: 90 },
                                        { label: 'DATA_ANALYTICS', val: 80 }
                                    ].map(stat => (
                                        <div key={stat.label}>
                                            <div className="flex justify-between text-xs mb-1">
                                                <span>{stat.label}</span>
                                                <span>{stat.val}%</span>
                                            </div>
                                            <div className="w-full h-2 bg-amber-900/30">
                                                <motion.div
                                                    initial={{ width: 0 }}
                                                    animate={{ width: `${stat.val}%` }}
                                                    transition={{ duration: 1, delay: 0.2 }}
                                                    className="h-full bg-amber-500"
                                                />
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                <div className="grid grid-cols-2 gap-4 mt-8">
                                    <div className="border border-amber-500/30 p-4 text-center">
                                        <div className="text-3xl font-bold mb-1">NEW</div>
                                        <div className="text-xs opacity-60">GRAD</div>
                                    </div>
                                    <div className="border border-amber-500/30 p-4 text-center">
                                        <div className="text-3xl font-bold mb-1">300K</div>
                                        <div className="text-xs opacity-60">LIVES_IMPACTED</div>
                                    </div>
                                </div>
                            </motion.div>
                        )}

                        {activeTab === 'history' && ( // Changed lore to history
                            <motion.div
                                key="history"
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="space-y-6 overflow-y-auto h-full pr-4"
                            >
                                <h2 className="text-2xl font-bold mb-4">&gt; HISTORY_LOGS</h2>

                                <div className="space-y-6 text-sm">
                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2025.11</span>
                                        <p className="opacity-90">Impact 100 Methodology deployed. Framework finalized for Western Canada Economic Forum to quantify cultural value.</p>
                                    </div>

                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2025.05 - 2025.08</span>
                                        <p className="opacity-90">RBC Product Manager (Amplify). Built Agentic AI solution for banking advisors. Filed patent for automated workflows.</p>
                                    </div>

                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2024.07 - 2025.04</span>
                                        <p className="opacity-90">City Strategy Protocol. Processed $1B+ in budget data for Saskatoon (300k+ citizens). Executed rigorous variance analysis.</p>
                                    </div>

                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2023.10 - 2024.08</span>
                                        <p className="opacity-90">Business Intelligence (ITS). Automated core data pipelines. Python/SQL/VBA stack. Drastically reduced operational overhead.</p>
                                    </div>

                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2023.08</span>
                                        <p className="opacity-90">Founded ESS node. Community fragmentation detected. Executed unification protocol. Status: Thriving.</p>
                                    </div>

                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2022.01 - 2022.07</span>
                                        <p className="opacity-90">Software Engineering Intern (Liviasoft). Deployed low-level C and Z80 Assembly. Bare metal optimization. 8086 architecture.</p>
                                    </div>

                                    <div className="border-l-2 border-amber-500 pl-4 py-1">
                                        <span className="text-xs opacity-50 block mb-1">LOG_2020.01 - 2022.11</span>
                                        <p className="opacity-90">Community Lead (Lead Nigeria). Orchestrated educational resource centers. IDP Camp outreach. Direct human impact.</p>
                                    </div>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>

                {/* Scanlines */}
                <div className="absolute inset-0 pointer-events-none opacity-10 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%]" />
            </div>
        </motion.div>
    );
};

export default GameIdentityCore;

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Project } from '../../types';
import GameProjectConsole from './GameProjectConsole';
import GameIdentityCore from './GameIdentityCore';
import GameCommsRelay from './GameCommsRelay';
import GameContactTerminal from './GameContactTerminal';
import GameBlogPlaceholder from './GameBlogPlaceholder';
import { renderGame } from './gameRenderer';

import GameA11yOverlay from './GameA11yOverlay';
import { IconArrow } from '../ui/Icons';
import { useGamePhysics, GamePhysicsState, GameObject } from '../../hooks/useGamePhysics';
import { useGameInput } from '../../hooks/useGameInput';
import { CONTACT_EMAIL } from '../../constants';

interface StoryModeProps {
    active: boolean;
    onExit: () => void;
    onSelectProject: (project: Project) => void;
}

type GameView = 'world' | 'project' | 'identity' | 'comms';

const StoryMode: React.FC<StoryModeProps> = ({ active, onExit, onSelectProject }) => {
    // View State
    const [currentView, setCurrentView] = useState<GameView>('world');

    // Modals State - these drive the overlays
    const [projectModal, setProjectModal] = useState<Project | null>(null);
    const [identityModal, setIdentityModal] = useState(false);
    const [contactModal, setContactModal] = useState(false);
    const [blogModal, setBlogModal] = useState(false);
    const [modalOriginRect, setModalOriginRect] = useState<{ x: number, y: number, w: number, h: number } | null>(null);

    // Gameplay State
    const [visitedNodes, setVisitedNodes] = useState<Set<string>>(new Set());

    // --- Interaction Callback ---
    const onInteract = useCallback((target: GameObject) => {
        setVisitedNodes(prev => new Set(prev).add(target.id));

        // Spatial Transition Calculation
        // Since we are inside the hook's callback, accessing refs directly is hard
        // But we can just use the target's position relative to the last known camera?
        // Actually, the hook handles the loop, but we need screen coords.
        // We will calc this roughly or use a center default if needed.
        // Better: We can access the camera ref if we pass it back?
        // Hook returns `cameraRef`.

        // We defer this briefly to let the physics hook usage settle.
        // For now, let's just trigger the state.

        if (target.type === 'project' && target.data) {
            setProjectModal(target.data);
            // We also select it in the parent app?
            // User requested: "onSelectProject(project)". 
            // In the original code, it set `currentView` to `project`.
            // Let's keep internal state for the modal.
            // onSelectProject(target.data); // This might close StoryMode if not handled carefully in page.tsx
        } else if (target.id === 'contact') {
            setContactModal(true);
        } else if (target.id === 'about') {
            setIdentityModal(true);
        } else if (target.id === 'blog') {
            setBlogModal(true);
        }
    }, [onSelectProject]); // Dependencies

    // --- Input & Physics Ref Sync ---
    // We need to bridge the "Physics says target is X" -> "Input says Interact" gap.
    const latestInteractionTarget = React.useRef<GameObject | null>(null);

    // --- Input Handlers ---
    const handleEscape = useCallback(() => {
        // Priority 1: Close Modals
        if (projectModal) {
            setProjectModal(null);
            return;
        }
        if (identityModal) {
            setIdentityModal(false);
            return;
        }
        if (contactModal) {
            setContactModal(false);
            return;
        }
        if (blogModal) {
            setBlogModal(false);
            return;
        }

        // Priority 2: Exit Game
        onExit();
    }, [projectModal, identityModal, contactModal, onExit]);

    const handleInputInteract = useCallback(() => {
        if (latestInteractionTarget.current) {
            onInteract(latestInteractionTarget.current);
        }
    }, [onInteract]);

    // --- Input Hook ---
    const inputKeys = useGameInput({
        active,
        onEscape: handleEscape,
        onInteract: handleInputInteract
    });

    // --- Physics Hook ---

    // Extracted Renderer
    const draw = useCallback((ctx: CanvasRenderingContext2D, state: GamePhysicsState) => {
        renderGame(ctx, state, visitedNodes);
    }, [visitedNodes]);

    // Use the Hook
    const physics = useGamePhysics({
        active,
        onInteract,
        onDraw: draw,
        onExit, // Legacy exit handler (passed for completeness)
        currentView,
        keys: inputKeys
    });

    // Sync Ref for Input Handler
    useEffect(() => {
        latestInteractionTarget.current = physics.interactionTarget;
    }, [physics.interactionTarget]);

    // We must handle setting modalOriginRect when interaction occurs.
    useEffect(() => {
        if (physics.interactionTarget && (physics.interactionTarget.type === 'project' || physics.interactionTarget.id === 'contact' || physics.interactionTarget.id === 'about')) {
            // But this effect runs whenever interactionTarget changes, which happens every frame during proximity.
            // We only want to set bounds when we *actually enter* the modal (triggered by onInteract).
            // So we do it in onInteract?
            // Yes, but we need camera pos.
            // onInteract is above. We need 'physics' variable to access cameraRef.
            // But 'physics' is defined *after* 'onInteract' because 'onInteract' is passed TO 'useGamePhysics'.
            // CIRCULAR DEPENDENCY.

            // Fix: Use a ref for camera that we pass TO the hook? Or let the hook return it and we use it in a separate effect?
            // The hook *returns* cameraRef.
            // But onInteract is a callback passed *to* the hook.
            // So inside onInteract, we can't see the 'physics' object constant yet.

            // Yes. When `projectModal` becomes non-null, capture current camera pos.
        }
    }, [physics]); // Added physics as dependency

    // Unified Escape Key Handler & Interaction
    // --- Manual Escape Logic Removed (Handled by useGameInput) ---

    // Effect to Capture Bounds on Modal Open
    useEffect(() => {
        if (projectModal || identityModal || contactModal || blogModal) {
            const cam = physics.cameraRef.current;
            const cvs = physics.canvasRef.current;
            // We need the target object.
            // It's likely `physics.interactionTarget`.
            const target = physics.interactionTarget;

            if (cam && cvs && target) {
                const cx = cvs.width / 2;
                const cy = cvs.height / 2;
                setModalOriginRect({
                    x: target.x - cam.x + cx,
                    y: target.y - cam.y + cy,
                    w: target.w,
                    h: target.h
                });
            }
        }
    }, [projectModal, identityModal, contactModal, blogModal]);

    // Helpers
    const MobileBtn = ({ dir }: { dir: string }) => (
        <button
            className="w-14 h-14 bg-white/10 backdrop-blur-md rounded-full border border-white/20 active:bg-pop/50 flex items-center justify-center transition-colors touch-none"
            onPointerDown={() => physics.handleMobileInput(dir, true)}
            onPointerUp={() => physics.handleMobileInput(dir, false)}
            onPointerLeave={() => physics.handleMobileInput(dir, false)}
        >
            <IconArrow className={`w-6 h-6 text-white ${dir === 'up' ? '-rotate-90' : dir === 'down' ? 'rotate-90' : dir === 'left' ? 'rotate-180' : ''}`} />
        </button>
    );

    if (!active) return null;

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className={`fixed inset-0 z-[100] bg-black text-white font-mono overflow-hidden touch-none ${physics.isHoveringObject ? 'cursor-pointer' : 'cursor-crosshair'}`}
        >
            <canvas
                ref={physics.canvasRef}
                className="block w-full h-full"
                {...physics.canvasHandlers}
            />

            {/* Accessibility Overlay */}
            <GameA11yOverlay
                active={active}
                objects={physics.objects.current}
                onInteract={onInteract}
            />

            {/* HUD */}
            {!projectModal && !identityModal && !contactModal && (
                <div className="absolute inset-0 pointer-events-none p-6 flex flex-col justify-between">
                    {/* Top Bar */}
                    <div className="flex justify-between items-start">
                        <div className="bg-black/80 backdrop-blur border border-white/20 p-4 rounded-sm flex gap-6">
                            <div>
                                <div className="flex items-center gap-2 mb-2">
                                    <div className="w-2 h-2 bg-green-500 animate-pulse rounded-full"></div>
                                    <h1 className="text-sm font-bold tracking-widest text-white">SYSTEM_STATUS: ACTIVE</h1>
                                </div>
                                <div className="text-[10px] text-white/50">
                                    MOUSE: ENABLED // TOUCH: ENABLED
                                </div>
                            </div>
                        </div>
                        <button onClick={onExit} className="pointer-events-auto bg-red-500/10 hover:bg-red-500 hover:text-white border border-red-500/50 text-red-500 px-4 py-2 text-xs font-bold tracking-widest transition-colors">[DISCONNECT]</button>
                    </div>

                    {/* Interaction Prompt - Always show if near target, regardless of hover */}
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-auto">
                        <AnimatePresence>
                            {physics.interactionTarget && (
                                <motion.div
                                    initial={{ y: 20, opacity: 0, scale: 0.9 }}
                                    animate={{
                                        y: [0, -5, 0],
                                        opacity: 1,
                                        scale: 1,
                                    }}
                                    exit={{ y: 20, opacity: 0, scale: 0.9 }}
                                    transition={{
                                        y: {
                                            repeat: Infinity,
                                            duration: 1.5,
                                            ease: "easeInOut"
                                        },
                                        opacity: { duration: 0.2 },
                                        scale: { duration: 0.2 }
                                    }}
                                    className="flex flex-col items-center gap-2"
                                >
                                    <motion.button
                                        onClick={() => onInteract(physics.interactionTarget!)}
                                        className="bg-white text-black px-8 py-4 font-bold shadow-[0_0_30px_rgba(255,255,255,0.5)] flex flex-col items-center gap-2 border-4 border-white cursor-pointer hover:bg-black hover:text-white transition-colors"
                                        onPointerDown={(e) => e.stopPropagation()}
                                        whileHover={{ scale: 1.05 }}
                                        whileTap={{ scale: 0.95 }}
                                    >
                                        <span className="text-sm tracking-widest">PRESS SPACE TO ENTER</span>
                                        <span className="text-xs tracking-wider opacity-80">{physics.interactionTarget.label}</span>
                                    </motion.button>
                                    <motion.div
                                        animate={{ opacity: [0.5, 1, 0.5] }}
                                        transition={{ repeat: Infinity, duration: 1.5 }}
                                        className="bg-black/80 backdrop-blur border border-white/40 px-4 py-2 text-[10px] tracking-widest text-white/90 hidden md:block"
                                    >
                                        [ SPACEBAR ] OR CLICK
                                    </motion.div>
                                    <motion.div
                                        animate={{ opacity: [0.5, 1, 0.5] }}
                                        transition={{ repeat: Infinity, duration: 1.5 }}
                                        className="bg-black/80 backdrop-blur border border-white/40 px-4 py-2 text-[10px] tracking-widest text-white/90 md:hidden"
                                    >
                                        TAP TO ENTER
                                    </motion.div>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>

                    {/* Mobile Controls */}
                    <div className="pointer-events-auto md:hidden grid grid-cols-3 gap-2 w-48 mx-auto mb-8">
                        <div></div><MobileBtn dir="up" /><div></div>
                        <MobileBtn dir="left" /><MobileBtn dir="down" /><MobileBtn dir="right" />
                    </div>
                </div>
            )}

            {/* Modals */}
            <AnimatePresence>
                {projectModal && (
                    <GameProjectConsole
                        project={projectModal}
                        onBack={() => setProjectModal(null)}
                        initialBounds={modalOriginRect}
                    />
                )}
                {identityModal && (
                    <GameIdentityCore
                        onBack={() => setIdentityModal(false)}
                        initialBounds={modalOriginRect}
                    />
                )}
                {contactModal && (
                    <GameContactTerminal
                        onBack={() => setContactModal(false)}
                        initialBounds={modalOriginRect}
                    />
                )}
                {blogModal && (
                    <GameBlogPlaceholder
                        onBack={() => setBlogModal(false)}
                        initialBounds={modalOriginRect}
                    />
                )}
            </AnimatePresence>

            {/* CRT Overlay */}
